INSERT INTO public.lightrag_doc_chunks VALUES ('chunk-3fa0dda35671b2abe8b70d8ad66268de', 'default', 'doc-a7bfdf72b46bd995a38a6edc5d3f7f97', 3, 1200, '放出されたものであると考えられている。また, アカク
