INSERT INTO public.lightrag_vdb_entity VALUES ('ent-62ee98b9ae5e4902f15be5f14549f982', 'default', 'オキクラゲ', 'オキクラゲ
山口県および和歌山県の沿岸域で多数個体が出現したと報告されたクラゲ。<SEP>学名*Pelagia noctiluca*。下関近海の沿岸で大量発生した鉢虫綱のクラゲの一種。<SEP>鉢虫綱に属し、下関近海で大発生したクラゲの一種。<SEP>山口県阿武町奈古筒尾と和歌山県白浜町番所崎の沿岸域で多数の個体の出現が報告されたクラゲです。<SEP>山口県阿武町奈古筒尾と和歌山県白浜町番所崎の沿岸域で多数個体の出現が見られたクラゲの一種。', '[-0.006087405,-0.01961142,-0.016460864,-0.06925801,0.010474517,0.0058599445,-0.024454553,0.00020112291,0.010145076,0.033381186,-0.0023580166,-0.0067775366,0.0013029589,0.0057137543,0.11484189,0.0031088102,0.0018596995,-0.0028833773,0.034172922,-0.016850032,0.01852406,0.0025244646,-0.00224347,-0.0143661285,-0.008138432,-0.01573564,0.01650792,-0.017094865,0.05414882,0.015988443,-0.028143056,0.032955416,-0.001857722,-0.032541227,0.0075004166,0.0010006275,0.019694095,-0.01715392,0.006430185,-0.004641698,-0.022902014,0.016903535,-0.013563437,0.00892674,0.009460128,-0.0061161676,-0.025704695,-0.016913261,0.009428098,0.0053836713,-0.015633903,0.002804702,-0.00726158,-0.18394202,0.012029112,0.003956816,0.0012404376,-0.003921174,0.02460965,0.0015161706,-0.01811921,0.0053648828,0.0066448613,-0.020173047,-0.02944157,0.001686761,-0.0042105457,0.016939234,-0.01420616,-0.0032986247,-0.017015431,-0.007974517,0.005746923,-0.00023977672,-0.00023136566,-0.014567572,0.029772766,0.03275491,-0.0075173625,0.020746114,0.018897919,-0.031707235,-0.023586543,-0.020748265,-0.013345105,-0.01768468,-0.016678547,-0.00805754,-0.008049876,0.01846856,0.0066751707,0.026561664,0.02013476,-0.011394105,-0.007251956,0.027075436,-0.018936368,-0.029490206,-0.0059786597,0.0016558357,-0.01764386,0.004985281,0.015730385,0.016517961,0.0045096134,-0.012818303,-0.0010301119,0.02191655,-0.004834382,0.015028965,0.0044190018,0.0145013565,-0.015603443,0.014540156,-0.010172719,-0.13753255,-0.02025807,0.01114714,-0.016696382,0.008039357,0.005740396,0.026134009,-0.009279229,-0.0005595024,-0.009725465,-0.03421503,0.004110967,-0.014061642,0.01193597,0.0030478484,0.027615467,-0.012698905,0.010174368,-0.015602927,1.0854764e-05,0.014339406,-0.0020461588,-0.014215242,0.0062836874,-0.009748942,-0.0107063865,0