INSERT INTO public.lightrag_vdb_entity VALUES ('ent-80dce2314364e8ac874ee9798b53f9a2', 'default', '刺胞動物', '刺胞動物
クラゲ類を含む動物の分類群。<SEP>クラゲを含む動物門で、化学物質を感知して行動を変化させることが明らかになっている。<SEP>刺傷反応を起こす動物群。<SEP>クラゲを含む動物門で、傘の内部に間充ゲルが発達し硬い支持組織を持たない。<SEP>クラゲ類を含む動物群で、多くは雌雄異体です。<SEP>クラゲ類を含む、刺胞を持つ動物の分類群(門)。', '[-0.0051298733,-0.014397841,0.0035035706,-0.026273934,-0.013870586,0.013546187,-0.005762473,0.017992713,0.028810475,-0.00802768,-0.030422324,-0.01959197,0.0043635946,-0.008087584,0.11373022,-0.011415429,0.0143305315,0.026309095,0.0037956545,-0.0323844,0.016483376,-0.03754177,0.019488892,-0.030232266,-0.027463267,-0.0039569368,0.037205786,-0.0012275802,0.032294773,0.013813552,-0.0067134183,0.031123059,0.01262151,-0.0025536658,0.01434064,-0.011735113,0.010090161,-0.010834747,-0.00049655425,0.008959935,-0.0097786,0.023493038,-0.01738107,0.011784206,0.028861623,0.009362467,0.029527891,-0.004598074,0.026815122,0.057318103,-0.017438268,0.01575677,-0.00076386076,-0.17227793,0.0021920756,0.025639093,-0.034117904,-0.02199495,0.012863385,0.002635559,-0.019213472,0.0099548185,-0.029179499,-0.036560066,-0.0020000539,-0.019009726,0.016372025,0.026895406,-0.033496846,0.00862736,0.01493639,0.03771332,-0.0153578855,-0.029882435,-0.01617797,-0.023353694,0.0043016938,0.015073624,0.004490543,0.031812724,0.0021843733,-0.03117967,-0.019851362,-0.023323862,0.011797271,-0.021900877,-0.019997085,-0.018211268,0.0052314126,0.031554155,0.00855452,-0.018510994,0.025656553,-0.031812444,-0.020035436,0.021843763,-0.018832194,-0.0047448403,0.00020017629,0.008258491,-0.013736977,0.0055085015,-0.020341085,-0.002738454,0.0096256435,-0.033120476,0.008325524,-0.010120879,0.007864204,0.009619822,0.011683224,0.011678083,-0.020939922,0.014814185,-0.031179907,-0.13739458,-0.008881069,-0.0040375483,-0.018807106,0.0070592184,0.0069976756,0.00071247685,0.012658649,0.032058604,-0.0054433653,-0.026145514,-0.0048376657,-0.025409438,0.021505883,-0.0015281946,0.002331743,-0.0112719955,0.0011034954,0.02220259,-0.008803504,0.013810501,-0.024616173,-0.006228619,-0.0015949103,0.0025284411,-0.025535202,0.025343426,0.0007165868,-0.030020406,0.010