INSERT INTO public.lightrag_vdb_entity VALUES ('ent-c4661bf0f0b7eab6ac197ac9c992eec5', 'default', 'ゼラチン質プランクトン', 'ゼラチン質プランクトン
山口県響灘沿岸域で季節的出現が研究されたプランクトンの一種。<SEP>クラゲに類似した柔らかい体をもつプランクトンの総称。<SEP>クラゲに類似した柔らかい体を持つプランクトンで、有櫛動物、軟体動物、脊索動物などが含まれる。本文ではクラゲ類として扱われる。<SEP>山口県響灘沿岸域で季節的出現が報告された生物群です。<SEP>柔らかい体を持つプランクトンの総称で、有櫛動物、軟体動物、脊索動物などが含まれ、本文ではクラゲ類として扱われる。<SEP>山口県響灘沿岸域における季節的出現が調査された生物群。', '[0.009865049,-0.010155285,-0.026077082,-0.049986515,0.018535592,0.010008577,0.0043098913,0.007889641,0.016350951,0.011505772,-0.022324057,-0.0037552358,-0.005774281,0.022911191,0.11978294,0.0048327358,0.0053447364,0.0283797,0.028799746,-0.014646712,0.018931793,-0.031408586,0.008945511,-0.0012222868,-0.0082806,-0.016140027,0.049315993,-0.00033252465,0.05498083,0.0038782142,0.0083125075,0.027480356,0.015941016,0.004986772,0.01661886,0.018258557,0.024013877,-0.003593015,0.020243732,0.019016081,-0.0168541,0.009522287,-0.036958046,0.02413606,0.019495092,-0.00687311,-0.024510238,-0.020060997,0.026390517,0.05017481,-0.006825213,-0.012482492,0.012274224,-0.16731612,0.00016617526,0.006456875,-0.013132668,-0.004585439,0.013288998,0.022463745,-0.023125608,0.005179527,-0.007737095,-0.02993615,-0.023121528,-0.017089283,0.004793014,0.028486583,-0.0046261963,-0.013927493,-0.0065705865,0.014761493,-0.007386529,-0.020021625,-0.0050499495,-0.021182466,0.023585822,0.015662335,0.01078149,0.02432043,0.029275106,-0.015617615,-0.021042228,-0.009332315,-0.008717929,-0.00365137,-0.012162981,-0.020769678,0.0021862944,0.046831124,-0.0057407836,0.0066299625,0.01679859,-0.016101968,-0.016024366,0.0077478206,-0.0065810117,-0.008842251,-0.005288957,-0.010096415,-0.006498548,0.011270242,-0.014568875,0.010606035,-0.0016711319,0.0064973775,-0.0017262305,0.02724459,-0.0056117345,0.0046940716,0.0024244103,0.000600137,-0.010780777,0.029267818,-0.031668697,-0.14694168,-0.006023094,-0.014660516,-0.0034385158,0.007696462,-0.011239922,0.006780234,-0.0014232687,0.0057420833,-0.025517626,-0.015708372,0.005785834,-0.024895092,0.026012335,0.004228913,0.0099980645,0.0042087375,0.010455477,-0.0100268,-0.0042047394,-0.019273365,-0.034148887,-0.022279408,0.011778