INSERT INTO public.lightrag_vdb_entity VALUES ('ent-6b4265a9fd7ed0e538a8a0a56cace111', 'default', 'アカクラゲ', 'アカクラゲ
学名*Chrysaora melanaster*。下関近海の沿岸で大量発生した鉢虫綱のクラゲの一種。<SEP>無機質、全N、Pなどの詳細な分析対象となっているクラゲの一種。<SEP>カミクラゲとの比較対象のクラゲの一種で、微量の(E)-2-nonenalが検出されたが、スニッフィングテストではにおいが感じられなかった。<SEP>餌となる生物、脂肪酸の組成と含量、リポキシゲナーゼなどの酵素の違いを調べる対象となるクラゲの一種。<SEP>学名Chrysaora pacificaを持つクラゲの一種で、魚のような生臭いにおいがします。<SEP>鉢虫綱に属し、下関近海で大発生したクラゲの一種。', '[0.029713916,-0.007862012,0.0056780125,-0.068754755,-0.004171559,-0.006872921,0.0041276375,0.00084092276,0.0050761704,0.01532655,-0.010720885,-0.009328388,0.029662566,-0.023641028,0.11679056,-0.005132908,-0.0092611015,0.00071550324,0.010218257,-0.026751453,0.02600052,-0.015273832,-0.008122429,-0.00250983,-0.01616012,-0.015520608,0.055391643,-0.0076672803,0.042221006,0.014969406,-0.02905754,0.029702539,0.025882453,-0.005355202,0.0035034816,0.015251572,0.015166519,-0.008119396,0.0064420374,0.007380252,-0.026504658,0.020838324,-0.023230754,0.0019696683,0.038265392,-0.010488329,0.005086982,-0.020930702,0.04261702,0.0016935526,-0.0032311468,0.021322988,-0.0020769765,-0.18020563,0.0024195064,0.026839234,-0.015606012,-0.016242232,0.027744517,-0.011355776,-0.013250365,0.009998245,-0.03410686,-0.036355156,-0.007840125,-0.008687638,0.009437409,0.015068628,-0.018419972,-0.0033029774,-0.013890379,0.012226789,0.0030053582,-0.005556225,-0.0018392154,-0.010263779,0.023878668,0.027469441,-0.019508254,0.012583756,0.012636237,-0.03516659,-0.019943435,-0.014772282,0.007454129,-0.028208857,-0.026051294,-0.028163947,-0.00336891,0.010283234,0.0026915523,0.008533517,0.0050276513,-0.01673934,-0.008317537,0.016918102,-0.0154864,-0.024795681,-0.01492426,0.024957435,-0.00060661987,0.014428194,0.0048102485,0.013387671,-0.0033985192,-0.026965378,0.005359974,-0.0014442158,-0.015958924,0.022936229,-0.0014264858,0.0015905793,-0.035240896,0.026080389,-0.014668806,-0.13946137,-0.007615885,-0.025799507,-0.01680854,-0.002018765,-0.013049665,0.007368709,0.018044507,0.0404005,-0.0027395594,-0.007598209,0.0029906882,-0.0164508,0.015202413,-0.0051225196,0.0144336475,-0.0007156581,-0.0031202736,-0.020923555,-0.01