INSERT INTO public.lightrag_vdb_entity VALUES ('ent-8a44f427e538668090c27203dc9982b0', 'default', 'カミクラゲ', 'カミクラゲ
学名*Spirocodon saltatrix*として知られ、一部では*Spirocodon saltator*とも記述されるカミクラゲは、ヒドロ虫綱に属するクラゲの一種です。このクラゲの最大の特徴は、独特で強いキュウリ様のにおいを放つ点にあります。GC/MS分析により、そのにおい物質として、(E)-2-nonenalや(E,Z)-2,6-nonadienalを含む7種類のC8およびC9揮発性化合物が検出されています。これらのにおい物質は、カミクラゲの防御や集合に役割を持つ可能性があると考えられており、その同定は研究対象となっています。

カミクラゲは、人間に対して刺傷被害を及ぼすような強力な毒性を有する刺胞は持っていません。生息域は日本と韓国の沿岸海域にわたり、特に東京湾での生息が確認されています。また、下関近海の沿岸では大量発生した事例も報告されています。この種は放卵や産卵を行うことが知られています。', '[0.02357467,-0.00586696,-0.012253664,-0.057619054,-0.003532286,-0.006789081,-0.014616875,-0.010617059,0.017676502,0.0011722795,-0.024133416,-0.00925726,-0.011839077,-0.0075195963,0.12660189,-0.007665308,-0.01959955,0.013759155,0.015963968,-0.028726542,0.017712833,0.0027858603,-0.0013932269,-0.012225302,-0.034148626,-0.030435283,0.029146278,-0.002837612,0.026548307,0.01281064,-0.01621346,0.043557182,-0.018473797,-0.002838881,-0.0024885496,-0.006733021,0.03172364,-0.02195733,0.0036898358,0.026551193,-0.015103794,0.015224338,0.008114572,-0.006168281,0.02117602,-0.006919381,-0.0074139447,-0.019485665,0.043876156,0.028482495,-0.0082331505,0.033526883,-0.0052710394,-0.1755993,0.022425463,0.035059083,-0.026224134,-0.023140004,0.012554569,-0.022406641,-0.007864862,0.01443886,-0.028533492,-0.013543339,0.0058490233,0.01393711,-0.015896576,0.02901623,-0.02947819,-0.012233449,0.010368099,0.021815669,0.0011874541,-0.022534398,0.014324788,-0.008828649,0.0076363054,0.012748844,-0.0030082671,-0.001324227,0.01577534,-0.04735091,-0.011194853,-0.015732935,0.01936299,-0.023723347,-0.026582653,-0.003069166,-0.013241805,0.020543138,0.021421129,-0.005883572,0.00026108982,-0.030659439,0.003150972,0.009446112,-0.0028599878,-0.021794824,-0.020721085,0.011147113,-0.022183804,0.00675731,0.0074077677,0.016983585,0.010860557,-0.010479983,0.003916574,-0.00029470882,-0.034445032,0.02133211,-0.00059298176,0.03809383,-0.017763011,0.0120936865,-0.017694237,-0.15679948,-0.00613333,-0.021491945,-0.0030957598,-0.011842823,-0.01382326,0.009027782,0.0077370293,0.024652695,-0.008241897,-0.006869544,0.009969598,-0.014539562,0.014215778,0.03358079,0.027323693,-0.0043039015,-0.012091974,-0.015113702,0.008123087,0.0048994087,0.022855753,-0.01603046,0.011126656,0.011863478,-0.017883413,0.0093960455,0.0037048531,-0.048965644,-0.002178142,-0.001010503,-0.007183563,0.01010574,-